    // Check if range is empty
    if (start == end) {
        return 0;
    }

    // Adjust start and end to include all even numbers in range
    if (start % 2 != 0) {
        start++;
    }
    if (end % 2 != 0) {
        end--;
    }

    // Calculate the number of even numbers in the range
