import java.util.Scanner;

public class PalindromeChecker {
    public static boolean isPalindrome(String sentence) {
        // Remove whitespace characters, punctuation marks, and special characters
        sentence = sentence.replaceAll("[^a-zA-Z0-9]", "").toLowerCase();

        // Check if the modified sentence is a palindrome
        int left = 0;
        int right = sentence.length() - 1;
        while (left < right) {
            if (sentence.charAt(left) != sentence.charAt(right)) {
                return false;
