Here is an example program that meets the requirements:

```cpp
#include <iostream>
#include <unordered_map>

std::unordered_map<long long, long long> fibMap;

long long fibonacci(long long n) {
    if (n <= 1) {
        return n;
    }

    // Check if Fibonacci number for given position has already been calculated
    if (fibMap.find(n) != fibMap.end()) {
        return fibMap[n];
    }

    // Calculate Fibonacci number recursively and store it in the map
    long long fib = fibonacci(n - 1) + fibonacci(n - 2);
    fibMap[n] = fib;

    return fib;
}

int main() {
    long long position;
    std::cout << "Enter the position (up to 1,000,000) to find the Fibonacci number: ";
    std::cin >> position;

    if (position < 0 || position > 1000000) {
        std::cout << "Invalid position entered. Please enter a value between 0 and 1,000,000." << std::endl;
        return 0;
    }

    long long result = fibonacci(position);
    std::cout << "Fibonacci number at position " << position << " is: " << result << std::endl;

    return 0;
}
