class DoublyLinkedList {
  constructor() {
    this.head = null;
    this.tail = null;
  }

  addNode(node) {
    if (!this.head) {
      this.head = node;
      this.tail = node;
    } else {
      node.next = this.head;
      this.head.prev = node;
      this.head = node;
    }
  }

  removeNode(node) {
    if (node.prev) {
      node.prev.next = node.next;
    } else {
      this.head = node.next;
    }

    if (node.next) {
      node.next.prev = node.prev;
    } else {
      this.tail = node.prev;
    }
  }

  moveToHead(node) {
    this.removeNode(node);
    this.addNode(node);
  }

  removeTail() {
    const tailKey = this.tail.key;
    this.removeNode(this.tail);
    return tailKey;
  }
}

class Dictionary {
  constructor() {
    this.capacity = 100;
    this.count = 0;
    this.head = null;
    this.tail = null;
    this.cache = new Map();
  }

  set(key, value) {
    if (this.cache.has(key)) {
      const node = this.cache.get(key);
      node.value = value;
      this.list.moveToHead(node);
    } else {
      const node = new Node(key, value);
      this.cache.set(key, node);
      this.list.addNode(node);
      this.count++;
      if (this.count > this.capacity) {
        const tailKey = this.list.removeTail();
        this.cache.delete(tailKey);
        this.count--;
      }
    }
  }

  get(key) {
    if (this.cache.has(key)) {
      const node = this.cache.get(key);
      this.list.moveToHead(node);
      return node.value;
    }
    return null;
  }

  removeNode(node) {
    this.list.removeNode(node);
    this.cache.delete(node.key);
    this.count--;
  }

  clear() {
    this.cache.clear();
    this.count = 0;
    this.head = null;
    this.tail = null;
  }
}
