function printPalindromicStrings(arr) {
  let palindromicStrings = [];
  let sumOfLengths = 0;

  // Iterate through the array
  for (let i = 0; i < arr.length; i++) {
    // Check if the current element is a string
    if (typeof arr[i] === 'string') {
      // Remove non-alphanumeric characters and convert to lowercase
      let string = arr[i].replace(/[^A-Za-z0-9]/g, '').toLowerCase();

      // Check if the string is a palindrome
      if (string === string.split('').reverse().join('')) {
        // Add the string to the palindromicStrings array
        palindromicStrings.push(string);
        // Add the length of the string to the sumOfLengths variable
        sumOfLengths += string.length;
      }
    }
  }

  // Sort the palindromicStrings array in ascending order
  palindromicStrings.sort();

  // Print the palindromic strings
  for (let i = 0; i < palindromicStrings.length; i++) {
    console.log(palindromicStrings[i]);
  }

  // Return the sum of the lengths of palindromic strings
