def get_weekday_dates(start_year, end_year):
    weekday_dict = {}

    for year in range(start_year, end_year + 1):
        for month in range(1, 13):
            for day in range(1, calendar.monthrange(year, month)[1] + 1):
                date = datetime.date(year, month, day)
                weekday = calendar.day_name[date.weekday()]

                if weekday not in weekday_dict:
                    weekday_dict[weekday] = []

                if date.weekday() < 5:  # Exclude weekends
                    weekday_dict[weekday].append(date.strftime("%Y-%m-%d"))

    # Remove holidays from the weekday lists
    holidays = ["2010-01-01", "2010-12-25", ...]  # List of holiday dates
    for holiday in holidays:
        for weekday_list in weekday_dict.values():
            if holiday in weekday_list:
                weekday_list.remove(holiday)

    # Sort the weekday_dict by the total number of dates for each weekday in descending order
    sorted_weekday_dict = dict(sorted(weekday_dict.items(), key=lambda x: len(x[1]), reverse=True))

