const MongoClient = require('mongodb').MongoClient;

class MongoDB {
  constructor(uri, options) {
    this.uri = uri;
    this.options = options;
    this.pool = [];
  }

  async connect() {
    const client = await MongoClient.connect(this.uri, this.options);
    const db = client.db();
    this.pool.push(db);
    return db;
  }

  async disconnect() {
    await Promise.all(this.pool.map(db => db.close()));
    this.pool = [];
  }

  getConnection() {
