sub check_circular_refs {
    my ($data, $seen_refs) = @_;

    if (ref $data eq 'HASH') {
        my $ref = Scalar::Util::refaddr($data);
        if (exists $seen_refs->{$ref}) {
            print "Circular reference detected!\n";
            return;
        }
        $seen_refs->{$ref} = 1;

        foreach my $value (values %$data) {
            if (ref $value eq 'HASH' or ref $value eq 'ARRAY') {
                check_circular_refs($value, $seen_refs);
            }
        }
        delete $seen_refs->{$ref};
    }
    elsif (ref $data eq 'ARRAY') {
        my $ref = Scalar::Util::refaddr($data);
        if (exists $seen_refs->{$ref}) {
            print "Circular reference detected!\n";
            return;
        }
        $seen_refs->{$ref} = 1;

        foreach my $element (@$data) {
            if (ref $element eq 'HASH' or ref $element eq 'ARRAY') {
                check_circular_refs($element, $seen_refs);
            }
        }
        delete $seen_refs->{$ref};
    }
}

sub process_data {
