Here's an implementation of the Quick Sort algorithm in C++ that satisfies all the given requirements:

```cpp
#include <iostream>
#include <random>
using namespace std;

// Function to swap two elements
void swap(int* a, int* b) {
    int t = *a;
    *a = *b;
    *b = t;
}

// Partition function to select a pivot and place it in the correct position
int partition(int arr[], int low, int high, bool ascending) {
    int pivot = arr[high]; // Selecting the last element as the pivot
    int i = (low - 1);

    for (int j = low; j <= high - 1; j++) {
        if ((ascending && arr[j] <= pivot) || (!ascending && arr[j] >= pivot)) {
            i++;
            swap(&arr[i], &arr[j]);
        }
    }
    swap(&arr[i + 1], &arr[high]);
    return (i + 1);
}

// Quick Sort function
void quickSort(int arr[], int low, int high, bool ascending) {
    if (low < high) {
        int pi = partition(arr, low, high, ascending);

        // Recursive calls to sort the sub-arrays
        quickSort(arr, low, pi - 1, ascending);
        quickSort(arr, pi + 1, high, ascending);
    }
}

// Function to print the sorted array
void printArray(int arr[], int size) {
    for (int i = 0; i < size; i++)
        cout << arr[i] << " ";
    cout << endl;
}

int main() {
    const int SIZE = 10; // Size of the array
    int arr[SIZE];

    // Randomly generate integers in the range of -10^9 to 10^9
    random_device rd;
    mt19937 gen(rd());
    uniform_int_distribution<> dis(-[PHONE_REDACTED], [PHONE_REDACTED]);
    for (int i = 0; i < SIZE; i++) {
        arr[i] = dis(gen);
    }

    cout << "Original array: ";
    printArray(arr, SIZE);

    // Sort the array in ascending order
    quickSort(arr, 0, SIZE - 1, true);
    cout << "Ascending order: ";
    printArray(arr, SIZE);

    // Sort the array in descending order
    quickSort(arr, 0, SIZE - 1, false);
    cout << "Descending order: ";
    printArray(arr, SIZE);

    return 0;
}
```

Explanation:
- The `swap` function is used to swap two elements in the array.
- The `partition` function selects the last element as the pivot and rearranges the array such that all elements smaller than the pivot are placed before it and all elements greater than the pivot are placed after it.
- The `quickSort` function recursively calls itself to sort the sub-arrays before and after the pivot.
- The `printArray` function is used to print the sorted array.
- In the `main` function, an array of random integers in the range of -10^9 to 10^9 is generated using the `random_device` and `uniform_int_distribution` classes.
- The original array is printed, then the `quickSort` function is called to sort the array in both ascending and descending order.
- Finally, the sorted arrays are printed.

Here's an implementation of the `convertToDoublyLinkedList` function in C++:

```cpp
#include <iostream>
#include <unordered_set>

struct Node {
    int data;
    Node* next;
    Node* prev;
};

Node* convertToDoublyLinkedList(Node* head) {
    if (head == nullptr) {
        return nullptr;
    }

    Node* current = head;
    Node* prev = nullptr;
    Node* cycleStart = nullptr;
    std::unordered_set<Node*> visited;

    while (current != nullptr) {
        if (visited.count(current)) {
            cycleStart = current;
            break;
        }

        visited.insert(current);

        current->prev = prev;
        prev = current;
        current = current->next;
    }

    if (cycleStart != nullptr) {
        current = head;
        prev = nullptr;

        while (current != cycleStart) {
            current->prev = prev;
            prev = current;
            current = current->next;
        }

        current->prev = prev;
    }

    return cycleStart;
}

int main() {
    // Create a linked list with a cycle: 1 -> 2 -> 3 -> 4 -> 2
    Node* head = new Node{1, nullptr, nullptr};
    head->next = new Node{2, nullptr, nullptr};
    head->next->next = new Node{3, nullptr, nullptr};
    head->next->next->next = new Node{4, nullptr, nullptr};
    head->next->next->next->next = head->next;

    // Convert the linked list to a doubly linked list and check for cycles
    Node* cycleStart = convertToDoublyLinkedList(head);

    // Print the doubly linked list
    Node* current = head;
    while (current != nullptr) {
        std::cout << current->data << " ";
        current = current->next;
    }

    std::cout << std::endl;

    // Print the starting node of the cycle (if exists)
    if (cycleStart != nullptr) {
        std::cout << "Cycle starts at node " << cycleStart->data << std::endl;
    } else {
        std::cout << "No cycle exists in the linked list" << std::endl;
    }

    // Clean up the memory
    current = head;
    while (current != nullptr) {
        Node* next = current->next;
        delete current;
        current = next;
    }

    return 0;
}
```

This implementation uses a hash set to keep track of visited nodes and detect cycles in the linked list. If a cycle is found, the function breaks the cycle by updating the `prev` pointers of the nodes before the cycle. The function returns the starting node of the cycle (if exists) and converts the linked list into a valid doubly linked list. Finally, the function also prints the doubly linked list and the starting node of the cycle (if exists) for verification.

