function formatEpochTime($epochTime) {
    // Check if the epoch time is within the valid range
    if ($epochTime < [PHONE_REDACTED]00 || $epochTime > 4133865600000) {
        throw new Exception('Invalid epoch time. Please provide a time between 1st January 2000 and 31st December 2100.');
    }

    // Calculate the milliseconds, seconds, minutes, hours, day, month, and year from the epoch time
    $milliseconds = $epochTime % 1000;
    $epochTime = floor($epochTime / 1000);
    $seconds = $epochTime % 60;
    $epochTime = floor($epochTime / 60);
    $minutes = $epochTime % 60;
    $epochTime = floor($epochTime / 60);
    $hours = $epochTime % 24;
    $epochTime = floor($epochTime / 24);

    // Add the number of days since 1st January 1970 to get the current date
    $date = gmdate('Y-m-d', $epochTime);

    // Extract the day, month, and year from the date
    list($year, $month, $day) = explode('-', $date);

    // Calculate the day of the week
    $dayOfWeek = date('l', strtotime($date));

    // Format the time with milliseconds as a 3-digit fraction
    $formattedTime = sprintf('%02d:%02d:%02d.%03d', $hours, $minutes, $seconds, $milliseconds);

    // Format the final date string
    $formattedDate = $dayOfWeek . ', ' . date('F d, Y', strtotime($date)) . ' ' . $formattedTime . ' GMT';

    return $formattedDate;
}

