import time

def fibonacci_iterative(n):
    fib_seq = [0, 1]
    for i in range(2, n):
        fib_seq.append(fib_seq[i-1] + fib_seq[i-2])
    return fib_seq

def fibonacci_recursive(n, memo={}):
    if n in memo:
        return memo[n]
    if n <= 1:
        return n
    memo[n] = fibonacci_recursive(n-1, memo) + fibonacci_recursive(n-2, memo)
    return memo[n]

def calculate_sum(sequence):
    return sum(sequence)

def validate_input(n):
    try:
        n = int(n)
        if n < 3 or n > 99:
            raise ValueError
        return n
    except ValueError:
        print("Invalid input. Please enter an integer between 3 and 99.")
        return None

def validate_method(method):
    if method.lower() not in ['iterative', 'recursive']:
        print("Invalid input. Please choose either 'iterative' or 'recursive'.")
        return None
    return method.lower()

def calculate_execution_time(start_time):
    return time.time() - start_time

def main():
    n = None
    while n is None:
        n = validate_input(input("Enter the value of n (between 3 and 99): "))

    method = None
    while method is None:
        method = validate_method(input("Choose method ('iterative' or 'recursive'): "))

