        fib_sequence = fibonacci_iterative(n)
        execution_time = calculate_execution_time(start_time)
    else:
        start_time = time.time()
        fib_sequence = [fibonacci_recursive(i) for i in range(n)]
        execution_time = calculate_execution_time(start_time)

    fib_sum = calculate_sum(fib_sequence)

    print("Fibonacci sequence up to the {}th term: {}".format(n, fib_sequence))
