```python
import threading

def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def find_primes(start, end, result):
    primes = []
    for i in range(start, end + 1):
        if i % 10 <= 5 and is_prime(i):
            primes.append(i)
    result.extend(primes)

def main():
    threads = [None] * 7
    result = []

    for i in range(len(threads)):
        start = i * (1000 // len(threads)) + 1
        end = (i + 1) * (1000 // len(threads))
        threads[i] = threading.Thread(target=find_primes, args=(start, end, result))
        threads[i].start()

    for thread in threads:
        thread.join()

    print(sorted(result))

if __name__ == "__main__":
    main()
```

