        print("Unknown sound")

class Dog(Animal):
    def make_sound(self):
        print("Woof")

class Cat(Animal):
    def make_sound(self):
        print("Meow")

def make_sound(animal):
    animal.make_sound()

dog = Dog()
make_sound(dog)  # Output: Woof

cat = Cat()
make_sound(cat)  # Output: Meow
```

