def time_to_minutes(time_str):
    # Check if the time is in 24-hour format
    if ':' in time_str:
        # Split the time into hours and minutes
        hours, minutes = time_str.split(':')
        # Check if the hours and minutes are valid
        if len(hours) == 2 and len(minutes) == 2 and hours.isdigit() and minutes.isdigit():
            hours = int(hours)
            minutes = int(minutes)
            # Check if the hours are valid
            if hours >= 0 and hours <= 23:
                # Check if the minutes are valid
                if minutes >= 0 and minutes <= 59:
                    # Calculate the time in minutes since midnight
                    return hours * 60 + minutes
                else:
                    raise ValueError('Invalid minutes')
            else:
                raise ValueError('Invalid hours')
        else:
            raise ValueError('Invalid time format')
    # Check if the time is in 12-hour format
    elif ' ' in time_str:
        # Split the time into hours, minutes, and AM/PM
        hours, minutes, am_pm = time_str.split(' ')
        # Check if the hours, minutes, and AM/PM are valid
        if len(hours) == 2 and len(minutes) == 2 and (am_pm == 'AM' or am_pm == 'PM') and hours.isdigit() and minutes.isdigit():
            hours = int(hours)
            minutes = int(minutes)
            # Check if the hours are valid
            if hours >= 1 and hours <= 12:
                # Check if the minutes are valid
                if minutes >= 0 and minutes <= 59:
                    # Adjust the hours based on AM/PM
                    if am_pm == 'PM':
                        hours += 12
                    # Calculate the time in minutes since midnight
                    return hours * 60 + minutes
                else:
                    raise ValueError('Invalid minutes')
            else:
                raise ValueError('Invalid hours')
        else:
            raise ValueError('Invalid time format')
    else:
        raise ValueError('Invalid time format')

