import java.util.HashMap;
import java.util.Map;
import java.util.Scanner;

public class FactorialCalculator {
    private static Map<Integer, Long> memoizationMap = new HashMap<>();

    public static void main(String[] args) {
        System.out.println("Welcome to the Factorial Calculator!");

        Scanner scanner = new Scanner(System.in);
        int number;

        do {
            System.out.print("Please enter a positive integer to calculate its factorial (or enter 0 to exit): ");
            while (!scanner.hasNextInt()) {
                System.out.println("Invalid input! Please enter a positive integer.");
                scanner.next();
            }
            number = scanner.nextInt();

            if (number < 0) {
                System.out.println("Error: Factorial of a negative number is undefined.");
                continue;
            }

            if (number == 0) {
                System.out.println("Exiting the program. Goodbye!");
                break;
            }

            long factorial = calculateFactorial(number);
            System.out.println("The factorial of " + number + " is: " + factorial);
        } while (true);

        scanner.close();
    }

    private static long calculateFactorial(int number) {
        if (number <= 1) {
            return 1;
        }

        if (memoizationMap.containsKey(number)) {
            return memoizationMap.get(number);
        }

        long factorial = number * calculateFactorial(number - 1);
        memoizationMap.put(number, factorial);
        return factorial;
    }
}
```

