import java.util.ArrayList;
import java.util.List;

public class ReverseAndSortList {

    public static List<String> reverseAndSort(List<String> inputList) {
        List<String> reversedAndSorted = new ArrayList<>();

        // Reverse the input list manually
        for (int i = inputList.size() - 1; i >= 0; i--) {
            reversedAndSorted.add(inputList.get(i));
        }

        // Sort the reversed list in alphabetical order
        mergeSort(reversedAndSorted, 0, reversedAndSorted.size() - 1);

        return reversedAndSorted;
    }

    private static void mergeSort(List<String> list, int left, int right) {
        if (left < right) {
            int mid = (left + right) / 2;

            mergeSort(list, left, mid);
            mergeSort(list, mid + 1, right);

            merge(list, left, mid, right);
        }
    }

    private static void merge(List<String> list, int left, int mid, int right) {
        int n1 = mid - left + 1;
        int n2 = right - mid;

        List<String> leftList = new ArrayList<>();
        List<String> rightList = new ArrayList<>();

        for (int i = 0; i < n1; i++) {
            leftList.add(list.get(left + i));
        }
        for (int i = 0; i < n2; i++) {
            rightList.add(list.get(mid + 1 + i));
        }

        int i = 0, j = 0, k = left;

        while (i < n1 && j < n2) {
            if (leftList.get(i).compareTo(rightList.get(j)) <= 0) {
                list.set(k, leftList.get(i));
                i++;
            } else {
                list.set(k, rightList.get(j));
                j++;
            }
            k++;
        }

        while (i < n1) {
            list.set(k, leftList.get(i));
            i++;
            k++;
        }

        while (j < n2) {
            list.set(k, rightList.get(j));
            j++;
            k++;
        }
    }

    public static void main(String[] args) {
        List<String> inputList = new ArrayList<>();
        inputList.add("apple");
        inputList.add("banana");
        inputList.add("carrot");
        inputList.add("date");

        List<String> reversedAndSorted = reverseAndSort(inputList);

        System.out.println("Reversed and Sorted List: " + reversedAndSorted);
    }
}
```

This implementation manually reverses the input list by iterating through it in reverse order and adding each element to the `reversedAndSorted` list. Then, it uses the Merge Sort algorithm to sort the reversed list in alphabetical order.

The `mergeSort` method divides the list into two halves recursively until each half has only one element. Then, it merges the two halves back together in sorted order. The `merge` method is used to merge the two halves while maintaining the alphabetical order.

