#define MAX_SIZE 1000000

// Function to check if a number is prime using bitwise operators
int isPrime(int n) {
    if (n <= 1)
        return 0;

    if (n <= 3)
        return 1;

    if ((n & 1) == 0 || (n % 3) == 0)
        return 0;

    int i = 5;
    while (i * i <= n) {
        if ((n % i) == 0 || (n % (i + 2)) == 0)
            return 0;
        i += 6;
    }

    return 1;
}

// Custom sorting algorithm to sort prime numbers in descending order
void customSort(int *arr, int n) {
    for (int i = 0; i < n - 1; i++) {
        for (int j = 0; j < n - i - 1; j++) {
            if (arr[j] < arr[j + 1]) {
                int temp = arr[j];
                arr[j] = arr[j + 1];
                arr[j + 1] = temp;
            }
        }
    }
}

int main() {
    int arr[MAX_SIZE];
    int primes[MAX_SIZE];
    int n;
    int primeCount = 0;

    printf("Enter the number of elements in the array: ");
    scanf("%d", &n);

    printf("Enter the elements of the array:\n");
    for (int i = 0; i < n; i++) {
        scanf("%d", &arr[i]);
    }

    // Find prime numbers in the array
    for (int i = 0; i < n; i++) {
        if (arr[i] > 0 && isPrime(arr[i])) {
            primes[primeCount] = arr[i];
            primeCount++;
        }
    }

    // Sort the prime numbers in descending order
    customSort(primes, primeCount);

    printf("Prime numbers in descending order:\n");
    for (int i = 0; i < primeCount; i++) {
        printf("%d ", primes[i]);
    }
    printf("\n");

    return 0;
}
```

Explanation:
- The program uses a bitwise implementation of the primality test to check if a number is prime or not.
- It prompts the user to enter the number of elements in the array and the array elements.
- Then, it iterates through the array to find the prime numbers and stores them in the `primes` array.
- After that, it uses the custom sorting algorithm `customSort` to sort the prime numbers in descending order.
- Finally, it prints the sorted prime numbers.

Note:
- The program assumes that the input array does not contain more than `MAX_SIZE` elements (1 million in this case).
- It also assumes that the input array does not contain more than `MAX_SIZE` prime numbers, as `primes` array has the same size.
