std::vector<char> findMostFrequentCharacters(const std::string& input) {
    std::unordered_map<char, int> characterCount;

    for (char c : input) {
        if (std::isalpha(c) && !std::isspace(c) && !std::ispunct(c)) {
            characterCount[c]++;
        }
    }

    int maxCount = 0;
    for (const auto& pair : characterCount) {
        maxCount = std::max(maxCount, pair.second);
    }

    std::vector<char> mostFrequentCharacters;
    for (const auto& pair : characterCount) {
        if (pair.second == maxCount) {
            mostFrequentCharacters.push_back(pair.first);
        }
    }

    std::sort(mostFrequentCharacters.begin(), mostFrequentCharacters.end());

    return mostFrequentCharacters;
}

int main() {
    std::string input;
    std::cout << "Enter a string: ";
    std::getline(std::cin, input);

    std::vector<char> mostFrequentCharacters = findMostFrequentCharacters(input);

    std::cout << "Most frequent characters: ";
    for (char c : mostFrequentCharacters) {
        std::cout << c << " ";
    }
    std::cout << std::endl;

    return 0;
}
