class Student:
    def __init__(self, name, age, gender):
        self.name = name
        self.age = age
        self.gender = gender
        self.grade = "Not assigned"

    def get_age_in_months(self):
        if self.age is None or self.age < 0:
            return "Invalid age"
        return self.age * 12

    def is_adult(self):
        return self.age >= 18

    def set_grade(self, grade):
        self.grade = grade

    def get_grade(self):
        return self.grade

    def get_info(self, include_grade=True):
        info = {
            'name': self.name,
            'age': self.age,
            'age_in_months': self.get_age_in_months(),
            'gender': self.gender
        }
        if include_grade:
            info['grade'] = self.grade
        return info

    def calculate_gpa(self):
        if self.grade is None or not self.is_valid_grade(self.grade):
            return 0
        if self.is_letter_grade(self.grade):
            return self.calculate_gpa_from_letter_grade(self.grade)
        else:
            return self.calculate_gpa_from_numerical_grade(self.grade)

    def is_valid_grade(self, grade):
        return self.is_letter_grade(grade) or self.is_numerical_grade(grade)

    def is_letter_grade(self, grade):
        return grade.upper() in ['A', 'B', 'C', 'D', 'F']

    def is_numerical_grade(self, grade):
        try:
            grade = float(grade)
            return 0 <= grade <= 100
        except ValueError:
            return False

    def calculate_gpa_from_letter_grade(self, grade):
        if grade.upper() == 'A':
            return 4.0
        elif grade.upper() == 'B':
            return 3.0
        elif grade.upper() == 'C':
            return 2.0
        elif grade.upper() == 'D':
            return 1.0
        else:
            return 0

    def calculate_gpa_from_numerical_grade(self, grade):
        if 90 <= float(grade) <= 100:
            return 4.0
        elif 80 <= float(grade) < 90:
            return 3.0
        elif 70 <= float(grade) < 80:
            return 2.0
        elif 60 <= float(grade) < 70:
            return 1.0
        else:
            return 0
