#include <stdio.h>
#include <stdbool.h>

void sieveOfEratosthenes(int n, bool prime[]) {
    for (int p = 2; p * p <= n; p++) {
        if (prime[p] == true) {
            for (int i = p * p; i <= n; i += p) {
                prime[i] = false;
            }
        }
    }
}

int main() {
    int lower, upper;
    printf("Enter the lower and upper bounds of the range: ");
    scanf("%d %d", &lower, &upper);

    // Create boolean array
    int size = upper + 1;
    bool prime[size];
    for (int i = 0; i <= upper; i++) {
        prime[i] = true;
    }

    // Mark 0 and 1 as false
    prime[0] = false;
    prime[1] = false;

    // Use Sieve of Eratosthenes algorithm
    sieveOfEratosthenes(upper, prime);

    // Display prime numbers and calculate sum
    int sum = 0;
    printf("Prime numbers within the range: ");
    for (int i = upper; i >= lower; i--) {
        if (prime[i] == true) {
            printf("%d ", i);
            sum += i;
        }
    }
    printf("\nSum of prime numbers: %d\n", sum);

    return 0;
}
