Here is a C++ program that sorts an array of strings in descending order based on the sum of the ASCII values of the characters in each string:

```cpp
#include <iostream>
#include <string>

using namespace std;

// Function to calculate the sum of ASCII values of characters in a string
int sumOfAscii(string str) {
    int sum = 0;
    for (char c : str) {
        sum += int(c);
    }
    return sum;
}

// Function to compare two strings for sorting
bool compareStrings(string str1, string str2) {
    int sum1 = sumOfAscii(str1);
    int sum2 = sumOfAscii(str2);

    if (sum1 == sum2) {
        return str1 > str2; // Sort alphabetically in descending order
    }
    return sum1 > sum2; // Sort by sum of ASCII values in descending order
}

// Function to perform bubble sort
void bubbleSort(string arr[], int n) {
    for (int i = 0; i < n - 1; i++) {
        for (int j = 0; j < n - i - 1; j++) {
            if (compareStrings(arr[j], arr[j + 1])) {
                // Swap arr[j] and arr[j+1]
                string temp = arr[j];
                arr[j] = arr[j + 1];
                arr[j + 1] = temp;
            }
        }
    }
}

int main() {
    int n;
    cout << "Enter the number of strings: ";
    cin >> n;

    string arr[n];
    cout << "Enter the strings: ";
    for (int i = 0; i < n; i++) {
        cin >> arr[i];
    }

    bubbleSort(arr, n);

    cout << "Sorted strings in descending order:" << endl;
    for (int i = 0; i < n; i++) {
        cout << arr[i] << endl;
    }

    return 0;
}
```

In this program, the `sumOfAscii` function calculates the sum of ASCII values of characters in a given string. The `compareStrings` function compares two strings based on their sum of ASCII values and alphabetically (if the sum is the same).

