import java.util.ArrayList;
import java.util.Date;
import java.util.List;

public class BankAccount {
    private String accountNumber;
    private String name;
    private double balance;
    private List<String> transactionHistory;

    // Constructor
    public BankAccount(String accountNumber, String name, double balance) {
        this.accountNumber = accountNumber;
        this.name = name;
        this.balance = balance;
        this.transactionHistory = new ArrayList<>();
    }

    // Getter and setter methods
    public String getAccountNumber() {
        return accountNumber;
    }

    public void setAccountNumber(String accountNumber) {
        this.accountNumber = accountNumber;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    public double getBalance() {
        return balance;
    }

    public void setBalance(double balance) {
        this.balance = balance;
    }

    // Deposit method
    public void deposit(double amount) throws IllegalArgumentException {
        if (amount <= 0) {
            throw new IllegalArgumentException("Invalid deposit amount");
        }
        balance += amount;
        String transactionRecord = "Date: " + new Date() + ", Type: Deposit, Amount: " + amount;
        transactionHistory.add(transactionRecord);
    }

    // Withdraw method
    public void withdraw(double amount) throws IllegalArgumentException {
        if (amount <= 0 || amount > balance) {
            throw new IllegalArgumentException("Invalid withdrawal amount");
        }
        balance -= amount;
        String transactionRecord = "Date: " + new Date() + ", Type: Withdrawal, Amount: " + amount;
        transactionHistory.add(transactionRecord);
    }

    // Get transaction history method
    public List<String> getTransactionHistory() throws IllegalStateException {
        if (transactionHistory.isEmpty()) {
            throw new IllegalStateException("Transaction history is empty");
        }
        return transactionHistory;
    }

    // Transfer method
    public void transfer(double amount, BankAccount targetAccount) throws IllegalArgumentException {
        if (amount <= 0 || amount > balance) {
            throw new IllegalArgumentException("Invalid transfer amount");
        }
        balance -= amount;
        targetAccount.balance += amount;

        String transactionRecord = "Date: " + new Date() + ", Type: Transfer, Amount: " + amount;
        transactionHistory.add(transactionRecord);
        targetAccount.transactionHistory.add(transactionRecord);
    }

    // Calculate interest method
    public double calculateInterest() {
        double interestRate = 0.05; // 5% per annum
        return balance * interestRate;
    }
}
```

