#include <stdio.h>

// Function to swap two integers
void swap(int* a, int* b) {
    int temp = *a;
    *a = *b;
    *b = temp;
}

// Function to perform partition for quicksort
int partition(int arr[], int low, int high) {
    int pivot = arr[high];
    int i = (low - 1);

    for (int j = low; j <= high - 1; j++) {
        if (arr[j] <= pivot) {
            i++;
            swap(&arr[i], &arr[j]);
        }
    }

    swap(&arr[i + 1], &arr[high]);

    return (i + 1);
}

// Function to implement quicksort
void quicksort(int arr[], int low, int high) {
    if (low < high) {
        int pi = partition(arr, low, high);

        quicksort(arr, low, pi - 1);
        quicksort(arr, pi + 1, high);
    }
}

// Function to remove duplicates from the array
int removeDuplicates(int arr[], int n) {
    int i, j;

    // Sort the array using quicksort
    quicksort(arr, 0, n - 1);

    // Traverse the sorted array and remove duplicates
    for (i = 0, j = 1; j < n; j++) {
        // If the current element is different from the previous element, store it at the next available position
        if (arr[j] != arr[i]) {
            i++;
            arr[i] = arr[j];
        }
    }

    // Return the new size of the array
    return i + 1;
}

// Function to print the array
void printArray(int arr[], int n) {
    for (int i = 0; i < n; i++) {
        printf("%d ", arr[i]);
    }
    printf("\n");
}

int main() {
    int arr[] = {1, -3, 2, -3, 4, 5, 2, 1, -5, 3};
    int n = sizeof(arr) / sizeof(arr[0]);

    printf("Original Array: ");
    printArray(arr, n);

    int newSize = removeDuplicates(arr, n);

    printf("Modified Array: ");
    printArray(arr, newSize);

    return 0;
}
```

