        self.left = None
        self.right = None

class MorseCodeConverter:
    def __init__(self):
        self.root = TreeNode('')

    def add_morse_code(self, character, morse_code):
        node = self.root
        for symbol in morse_code:
            if symbol == '.':
                if node.left is None:
                    node.left = TreeNode('')
                node = node.left
            elif symbol == '-':
                if node.right is None:
                    node.right = TreeNode('')
                node = node.right
        if node.value != '':
            node.value += '_'  # Unique identifier for duplicate character
        node.value += character

    def remove_morse_code(self, character):
        self._remove_morse_code_recursive(self.root, character)

    def _remove_morse_code_recursive(self, node, character):
        if node is None:
            return None
        elif character < node.value:
            node.left = self._remove_morse_code_recursive(node.left, character)
        elif character > node.value:
            node.right = self._remove_morse_code_recursive(node.right, character)
        else:
            if node.left is None and node.right is None:
                return None
            elif node.left is None:
                return node.right
            elif node.right is None:
                return node.left
            else:
                successor = self._find_successor(node.right)
                node.value = successor.value
                node.right = self._remove_morse_code_recursive(node.right, successor.value)
        return node

    def _find_successor(self, node):
        current = node
        while current.left is not None:
            current = current.left
        return current

    def convert_to_morse_code(self, text):
        morse_code = []
        for character in text:
            node = self.root
            if character == ' ':
                morse_code.append(' ')
            else:
                while node is not None:
                    if character == node.value:
                        break
                    elif character < node.value:
                        node = node.left
                    else:
                        node = node.right
                if node is None:
                    morse_code.append('!')  # Erroneous code: Indicates invalid character
                else:
                    morse_code.append(node.value)
        return morse_code

    def convert_from_morse_code(self, morse_code):
        text = ''
        for symbol in morse_code:
            if symbol == ' ':
                text += ' '
            elif symbol == '!':
                text += '?'
            else:
                node = self.root
                for dot_dash in symbol:
                    if dot_dash == '.':
                        node = node.left
                    elif dot_dash == '-':
                        node = node.right
                if node is None or node.value == '':
                    text += '?'
                else:
                    text += node.value
        return text

    def get_longest_sequence(self):
        longest_sequence = ''
        self._get_longest_sequence_recursive(self.root, '', longest_sequence)
        return longest_sequence

    def _get_longest_sequence_recursive(self, node, current_sequence, longest_sequence):
        if node is None:
            return
        if len(current_sequence) > len(longest_sequence):
            longest_sequence = current_sequence
        self._get_longest_sequence_recursive(node.left, current_sequence + '.', longest_sequence)
        self._get_longest_sequence_recursive(node.right, current_sequence + '-', longest_sequence)
