To detect the data type of a given variable and handle nested structures efficiently, you can use recursion to iterate through the variable and its nested elements. Here's a code implementation in Python:

```python
def detect_data_type(var):
    if isinstance(var, int):
        return "integer"
    elif isinstance(var, float):
        return "float"
    elif isinstance(var, str):
        return "string"
    elif isinstance(var, list):
        return "list"
    elif isinstance(var, dict):
        return "dictionary"
    elif isinstance(var, tuple):
        return "tuple"
    elif isinstance(var, set):
        return "set"
    elif hasattr(var, '__class__') and not isinstance(var, type):
        return "custom object"
    else:
        return "unknown"

def detect_data_type_recursive(var, depth=0):
    if depth > 10:
        return "unknown"
    if isinstance(var, (list, tuple)):
        for element in var:
            result = detect_data_type_recursive(element, depth + 1)
            if result != "unknown":
                return result
    elif isinstance(var, dict):
        for key, value in var.items():
            result_key = detect_data_type_recursive(key, depth + 1)
            result_value = detect_data_type_recursive(value, depth + 1)
            if result_key != "unknown" or result_value != "unknown":
                return "dictionary"
    return detect_data_type(var)
```

