import java.util.Scanner;

public class KthLargestElement {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Enter the length of the array: ");
        int length = scanner.nextInt();

        int[] arr = new int[length];
        System.out.println("Enter the elements of the array: ");
        for (int i = 0; i < length; i++) {
            arr[i] = scanner.nextInt();
        }

        System.out.print("Enter the value of k: ");
        int k = scanner.nextInt();

        int kthLargest = findKthLargest(arr, k);
        System.out.println("The kth largest element is: " + kthLargest);
    }

    public static int findKthLargest(int[] arr, int k) {
        return quickSelect(arr, 0, arr.length - 1, k);
    }

    private static int quickSelect(int[] arr, int low, int high, int k) {
        int pivotIndex = partition(arr, low, high);

        if (pivotIndex == k - 1) {
            return arr[pivotIndex];
        } else if (pivotIndex < k - 1) {
            return quickSelect(arr, pivotIndex + 1, high, k);
        } else {
            return quickSelect(arr, low, pivotIndex - 1, k);
        }
    }

    private static int partition(int[] arr, int low, int high) {
        int pivot = arr[high];
        int i = low - 1;

        for (int j = low; j < high; j++) {
            if (arr[j] > pivot) {
                i++;
                swap(arr, i, j);
            }
        }

        swap(arr, i + 1, high);
        return i + 1;
    }

    private static void swap(int[] arr, int i, int j) {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }
}

Here's a Java program that lists all prime numbers between m and n using a multi-threaded approach:

```java
import java.util.ArrayList;
import java.util.List;

class PrimeThread extends Thread {
    private int start;
    private int end;
    private List<Integer> primes;

    public PrimeThread(int start, int end) {
        this.start = start;
        this.end = end;
        this.primes = new ArrayList<>();
    }

    @Override
    public void run() {
        for (int number = start; number <= end; number++) {
            if (isPrime(number)) {
                synchronized (primes) {
                    primes.add(number);
                }
            }
        }
    }

    private boolean isPrime(int number) {
        if (number <= 1) {
            return false;
        }

        for (int i = 2; i <= Math.sqrt(number); i++) {
            if (number % i == 0) {
                return false;
            }
        }

        return true;
    }

    public List<Integer> getPrimes() {
        return primes;
    }
}

public class PrimeNumberFinder {
    public static void main(String[] args) {
        int m = 1; // Start of range
        int n = 100; // End of range
        int numThreads = 4; // Number of threads

        List<PrimeThread> threads = new ArrayList<>();

        // Divide the range into equal parts for each thread
        int range = n - m + 1;
        int partitionSize = range / numThreads;
        int remaining = range % numThreads;

        for (int i = 0; i < numThreads; i++) {
            int start = m + (i * partitionSize);
            int end = start + partitionSize - 1;

            if (i == numThreads - 1) {
                end += remaining;
            }

            PrimeThread thread = new PrimeThread(start, end);
            threads.add(thread);
            thread.start();
        }

        List<Integer> allPrimes = new ArrayList<>();

        for (PrimeThread thread : threads) {
            try {
                thread.join();
                allPrimes.addAll(thread.getPrimes());
            } catch (InterruptedException e) {
                e.printStackTrace();
            }
        }

        int product = 1;
        for (int prime : allPrimes) {
            product *= prime;
        }

        System.out.println("Prime numbers between " + m + " and " + n + ": " + allPrimes);
        System.out.println("Product of prime numbers: " + product);
    }
}
```

This program divides the range of numbers between m and n into equal parts and assigns each part to a separate thread. Each thread checks if each number within its range is prime and adds it to a shared list of primes if it is. Synchronization is achieved using the `synchronized` keyword when adding prime numbers to the shared list. Finally, the program calculates the product of all prime numbers found and displays the list of prime numbers and their product.

