import math

class MassDistribution:
    def __init__(self, mass, position):
        self.mass = mass
        self.position = position

def calculate_distance(point1, point2):
    x1, y1, z1 = point1.position
    x2, y2, z2 = point2.position
    distance = math.sqrt((x2 - x1)**2 + (y2 - y1)**2 + (z2 - z1)**2)
    return distance

def calculate_gravitational_force(point1, point2):
    G = 6.67430e-11
    m1 = point1.mass
    m2 = point2.mass
    r = calculate_distance(point1, point2)
    force = G * ((m1 * m2) / r**2)
    return force

def main():
    num_distributions = int(input("Enter the number of mass distributions: "))
    distributions = []

    for i in range(num_distributions):
        mass_distribution = MassDistribution(float(input("Enter the mass of the point: ")), 
                                             tuple(map(float, input("Enter the position of the point (x, y, z): ").split())))
        distributions.append(mass_distribution)

    total_force = 0
    for i in range(num_distributions):
        for j in range(i+1, num_distributions):
            distribution1 = distributions[i]
            distribution2 = distributions[j]
            for point1 in distribution1:
                for point2 in distribution2:
                    force = calculate_gravitational_force(point1, point2)
                    total_force += force

    print("Total gravitational force between all pairs of points in different mass distributions:", total_force)

