public class BubbleSortDescending {

  public static void bubbleSortDescending(int[] array) {
    int n = array.length;

    for (int i = 0; i < n - 1; i++) {
      for (int j = 0; j < n - i - 1; j++) {
        if (array[j] < array[j + 1]) {
          int temp = array[j];
          array[j] = array[j + 1];
          array[j + 1] = temp;
        }
      }
    }
  }

  public static void main(String[] args) {
    int[] array = {5, 8, 2, 1, 6, 3, 7, 4};

