  // Create a date object with a fixed date and time
  const fixedDate = new Date('2022-01-01T00:00:00.000Z');

  // Get the UTC timestamp of the fixed date
  const fixedTimestamp = fixedDate.getTime();

  // Create a date object with the current date and time
  const currentDate = new Date();

  // Get the UTC timestamp of the current date
  const currentTimestamp = currentDate.getTime();

  // Calculate the difference in milliseconds between the fixed and current timestamps
  const timestampDiff = currentTimestamp - fixedTimestamp;

  // Convert the difference to minutes
  const offsetInMinutes = Math.floor(timestampDiff / 60000);

