Here's an example program written in Python that compares the time complexity of accessing elements in a linked list and an array:

```python
import random
import time

class Node:
    def __init__(self, data):
        self.data = data
        self.next = None

class LinkedList:
    def __init__(self):
        self.head = None

    def add_element(self, data):
        new_node = Node(data)
        if self.head is None:
            self.head = new_node
        else:
            current = self.head
            while current.next is not None:
                current = current.next
            current.next = new_node

    def access_element(self, index):
        current = self.head
        for _ in range(index):
            if current is None:
                raise IndexError("Index out of range")
            current = current.next
        return current.data

def array_access(array, index):
    return array[index]

def measure_access_time(data_structure, size, index, iterations):
    total_time = 0
    for _ in range(iterations):
        start_time = time.time()
        data_structure(size).access_element(index)
        end_time = time.time()
        total_time += end_time - start_time
    average_time = total_time / iterations
    return average_time

def compare_data_structures(size, index, iterations):
    linked_list_time = measure_access_time(LinkedList, size, index, iterations)
    array_time = measure_access_time(list, size, index, iterations)

    print(f"Average access time for linked list: {linked_list_time:.6f} seconds")
    print(f"Average access time for array: {array_time:.6f} seconds")

    if linked_list_time < array_time:
        print("Based on the results, using a linked list is more efficient for the given number of elements.")
    elif linked_list_time > array_time:
        print("Based on the results, using an array is more efficient for the given number of elements.")
    else:
        print("Based on the results, both data structures have similar efficiency.")

# Example usage
