bool isPrime(int num) {
    if (num < 2) {
        return false;
    }
    for (int i = 2; i <= sqrt(num); i++) {
        if (num % i == 0) {
            return false;
        }
    }
    return true;
}

// Function to calculate the sum of the digits of a number
int sumOfDigits(int num) {
    int sum = 0;
    while (num > 0) {
        sum += num % 10;
        num /= 10;
    }
    return sum;
}

// Function to find the maximum sum of strictly increasing prime numbers in a diagonal pattern
int findMaxDiagonalSum(vector<vector<int>>& matrix) {
    int maxSum = 0;
    int rows = matrix.size();
    int cols = matrix[0].size();

    // Iterate over each element in the matrix
    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            // If the current element is a prime number
            if (isPrime(matrix[i][j])) {
                int currentSum = matrix[i][j];  // Start with the current element
                int x = i;
                int y = j;

                // Move diagonally until the next element is a strictly increasing prime number
                while (x < rows - 1 && y < cols - 1 && isPrime(matrix[x + 1][y + 1]) && matrix[x + 1][y + 1] > matrix[x][y] && sumOfDigits(matrix[x + 1][y + 1]) > 1) {
                    currentSum += matrix[x + 1][y + 1];
                    x++;
                    y++;
                }

                // Update the maximum sum if the current sum is greater
                if (currentSum > maxSum) {
                    maxSum = currentSum;
                }
            }
        }
    }

    return maxSum;
