```cpp
#include <iostream>
#include <vector>

using namespace std;

vector<int> generatePrimes(int n) {
    vector<bool> isPrime(n + 1, true);
    vector<int> primes;

    for (int p = 2; p * p <= n; p++) {
        if (isPrime[p]) {
            for (int i = p * p; i <= n; i += p)
                isPrime[i] = false;
        }
    }

    for (int p = 2; p <= n; p++) {
        if (isPrime[p])
            primes.push_back(p);
    }

    return primes;
}

int main() {
    vector<int> primes = generatePrimes(542);

    int sum = 0;
    for (int i = 0; i < 100; i++) {
        sum += primes[i];
    }

    cout << "Sum of the first 100 prime numbers: " << sum << endl;

    return 0;
}
