```python
class Node:
    def __init__(self, data):
        self.data = data
        self.next = None
        self.prev = None

class DoublyLinkedList:
    def __init__(self):
        self.head = None

    def append(self, data):
        new_node = Node(data)
        if self.head is None:
            self.head = new_node
        else:
            current = self.head
            while current.next:
                current = current.next
            current.next = new_node
            new_node.prev = current

    def bubble_sort(self):
        if self.head is None:
            return

        end = None
        while end != self.head:
            current = self.head
            while current.next != end:
                if current.data > current.next.data:
                    self._swap(current, current.next)
                current = current.next
            end = current

    def _swap(self, node1, node2):
        if node1 == node2:
            return

        if node1.next == node2:
            node1.next = node2.next
            if node2.next:
                node2.next.prev = node1
            node2.prev = node1.prev
            if node1.prev:
                node1.prev.next = node2
            node2.next = node1
            node1.prev = node2
        else:
            node1.prev.next = node2
            node2.next.prev = node1

            temp = node1.next
            node1.next = node2.next
            node2.next = temp

            temp = node1.prev
            node1.prev = node2.prev
            node2.prev = temp

            if node1.next:
                node1.next.prev = node1
            if node2.next:
                node2.next.prev = node2
            if node1.prev:
                node1.prev.next = node1
            if node2.prev:
                node2.prev.next = node2

    def display(self):
        current = self.head
        while current:
            print(current.data, end=" ")
            current = current.next
        print()

# Usage example
