    public static BigInteger sumOfEvenNumbers(int[] arr) {
        BigInteger sum = BigInteger.ZERO;

        for (int i = 0; i < arr.length; i++) {
            try {
                BigInteger num = new BigInteger(Integer.toString(arr[i]));

