    public static boolean isPerfectNumber(long num) {
        if (num <= 1) {
            return false;
        }

        long sum = 1;

        for (long i = 2; i * i <= num; i++) {
            if (num % i == 0) {
                sum += i;

                if (i * i != num) {
                    sum += num / i;
                }
            }
        }

        return sum == num;
    }

