public static double power(double x, int n) {
    if (n == 0) {
        return 1;
    }
    if (n < 0) {
        x = 1 / x;
        n = -n;
    }
    double result = 1;
    for (int i = 1; i <= n; i++) {
        result *= x;
    }
    return result;
}
```

