def find_longest_substring(string, k):
    if len(string) == 0:
        return None

    if k <= 0:
        return None

    substring_count = {}
    max_length = 0
    max_substring = ""

    for i in range(len(string)):
        for j in range(i+1, len(string)+1):
            substring = string[i:j]

            if substring not in substring_count:
                substring_count[substring] = 1
            else:
