```java
public static void printAndSumPrimes(int limit) {
    // Initialize a boolean array to track the prime numbers
    boolean[] primes = new boolean[limit + 1];
    Arrays.fill(primes, true);
    primes[0] = primes[1] = false;

    long sum = 0;

    // Iterate through the numbers up to the square root of the limit
    for (int i = 2; i * i <= limit; i++) {
        // If a number is prime, mark all its multiples as non-prime
        if (primes[i]) {
            for (int j = i * i; j <= limit; j += i) {
                primes[j] = false;
            }
        }
    }

    // Print and calculate the sum of all prime numbers
    for (int i = 2; i <= limit; i++) {
        if (primes[i]) {
            System.out.println(i);
            sum += i;
        }
    }

    System.out.println("Sum of all prime numbers: " + sum);
}
