```cpp
#include <iostream>
#include <string>
#include <cctype>

std::string capitalizeWords(const std::string& input) {
    std::string result;
    bool capitalizeNext = true;

    for (char c : input) {
        if (std::isalpha(c)) {
            if (capitalizeNext) {
                result += std::toupper(c);
                capitalizeNext = false;
            } else {
                result += std::tolower(c);
            }
        } else if (std::isspace(c)) {
            capitalizeNext = true;
            result += c;
        } else {
            result += c;
        }
    }

    return result;
}

int main() {
    std::string input = "hello WORLD! hOW Are you? 12345 #special";
    std::string output = capitalizeWords(input);
    std::cout << output << std::endl;

    return 0;
}
