Here's an implementation of a hash table in C programming language with 7 buckets, collision-free hash function, and resizing mechanism:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define INITIAL_BUCKET_COUNT 7
#define LOAD_FACTOR_THRESHOLD_HIGH 0.7
#define LOAD_FACTOR_THRESHOLD_LOW 0.3

typedef struct {
    char* key;
    int value;
} Node;

typedef struct {
    Node** buckets;
    int count;
    int size;
} HashTable;

int hashFunction(const char* key, int size) {
    int sum = 0;
    for (int i = 0; i < strlen(key); i++) {
        sum += key[i];
    }
    return sum % size;
}

HashTable* createHashTable() {
    HashTable* hashTable = (HashTable*)malloc(sizeof(HashTable));
    hashTable->count = 0;
    hashTable->size = INITIAL_BUCKET_COUNT;
    hashTable->buckets = (Node**)calloc(INITIAL_BUCKET_COUNT, sizeof(Node*));
    return hashTable;
}

void resizeHashTable(HashTable* hashTable, int newSize) {
    Node** newBuckets = (Node**)calloc(newSize, sizeof(Node*));
    for (int i = 0; i < hashTable->size; i++) {
        if (hashTable->buckets[i] != NULL) {
            int newIndex = hashFunction(hashTable->buckets[i]->key, newSize);
            while (newBuckets[newIndex] != NULL) {
                newIndex = (newIndex + 1) % newSize;
            }
            newBuckets[newIndex] = hashTable->buckets[i];
        }
    }
    free(hashTable->buckets);
    hashTable->buckets = newBuckets;
    hashTable->size = newSize;
}

void insert(HashTable* hashTable, const char* key, int value) {
    if ((double)hashTable->count / hashTable->size >= LOAD_FACTOR_THRESHOLD_HIGH) {
        resizeHashTable(hashTable, hashTable->size * 2);
    }

    int index = hashFunction(key, hashTable->size);
    while (hashTable->buckets[index] != NULL) {
        if (strcmp(hashTable->buckets[index]->key, key) == 0) {
            printf("Error: Key already exists\n");
            return;
        }
        index = (index + 1) % hashTable->size;
    }

    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->key = strdup(key);
    newNode->value = value;
    hashTable->buckets[index] = newNode;
    hashTable->count++;
}

void delete(HashTable* hashTable, const char* key) {
    int index = hashFunction(key, hashTable->size);
    while (hashTable->buckets[index] != NULL) {
        if (strcmp(hashTable->buckets[index]->key, key) == 0) {
            free(hashTable->buckets[index]->key);
            free(hashTable->buckets[index]);
            hashTable->buckets[index] = NULL;
            hashTable->count--;

            if ((double)hashTable->count / hashTable->size <= LOAD_FACTOR_THRESHOLD_LOW) {
                resizeHashTable(hashTable, hashTable->size / 2);
            }

            return;
        }
        index = (index + 1) % hashTable->size;
    }
    printf("Error: Key does not exist\n");
}

int search(HashTable* hashTable, const char* key) {
    int index = hashFunction(key, hashTable->size);
    while (hashTable->buckets[index] != NULL) {
        if (strcmp(hashTable->buckets[index]->key, key) == 0) {
            return hashTable->buckets[index]->value;
        }
        index = (index + 1) % hashTable->size;
    }
    printf("Error: Key does not exist\n");
    return -1;
}

double getLoadFactor(HashTable* hashTable) {
    return (double)hashTable->count / hashTable->size;
}

void destroyHashTable(HashTable* hashTable) {
    for (int i = 0; i < hashTable->size; i++) {
        if (hashTable->buckets[i] != NULL) {
            free(hashTable->buckets[i]->key);
            free(hashTable->buckets[i]);
        }
    }
    free(hashTable->buckets);
    free(hashTable);
}

int main() {
    HashTable* hashTable = createHashTable();

    insert(hashTable, "John", 25);
    insert(hashTable, "Jane", 30);
    insert(hashTable, "Alice", 35);
    insert(hashTable, "Bob", 40);
    insert(hashTable, "Eve", 45);

    printf("Search result for key 'Jane': %d\n", search(hashTable, "Jane"));
    printf("Search result for key 'Eve': %d\n", search(hashTable, "Eve"));
    printf("Search result for key 'John': %d\n", search(hashTable, "John"));
    printf("Search result for key 'Bob': %d\n", search(hashTable, "Bob"));
    printf("Search result for key 'Alice': %d\n", search(hashTable, "Alice"));

    delete(hashTable, "Bob");
    delete(hashTable, "Alice");

    printf("Search result for key 'Alice' after deletion: %d\n", search(hashTable, "Alice"));
    printf("Search result for key 'Bob' after deletion: %d\n", search(hashTable, "Bob"));

    printf("Current load factor: %lf\n", getLoadFactor(hashTable));

    destroyHashTable(hashTable);
    return 0;
}
```

This implementation creates a hash table using the `HashTable` struct, which contains an array of `Node` pointers as buckets, along with the count of elements and the current size. The `Node` struct holds the key-value pairs.

The `hashFunction` calculates the hash value of a given key by summing up the ASCII values of its characters and then taking the modulus of the size.

The `createHashTable` function initializes the hash table with the initial number of buckets and allocates memory for the buckets array.

The `resizeHashTable` function is responsible for resizing the hash table when the load factor exceeds the threshold. It creates a new array of buckets with the new size, rehashes all the elements from the old array into the new array, and updates the hash table's size and buckets pointer.

The `insert` function inserts a new key-value pair into the hash table. If the load factor exceeds the threshold, it triggers a resize. It uses linear probing to handle collisions and throws an exception if the key already exists.

The `delete` function removes a key-value pair from the hash table. It uses linear probing to find the key and throws an exception if the key does not exist. If the load factor falls below the threshold, it triggers a resize.

The `search` function looks for a key in the hash table and returns the associated value. It uses linear probing to find the key and throws an exception if the key does not exist.

The `getLoadFactor` function calculates and returns the current load factor of the hash table.

The `destroyHashTable` function frees the allocated memory for the hash table, including the keys and nodes in the buckets.

In the `main` function, we create a hash table, insert some key-value pairs, perform search and delete operations, and print the load factor before destroying the hash table.

Note: This implementation assumes that the keys are unique and does not handle hash collisions beyond linear probing. If multiple keys result in the same hash value, they will be placed in the next available bucket.

