```python
def is_prime(n, divisor):
    if n <= 2:
        return True
    if n % divisor == 0:
        return False
    if divisor * divisor > n:
        return True
    return is_prime(n, divisor + 1)

def print_primes(start, end):
    if start > end:
        return

    if is_prime(start, 2):
        print(start)

    print_primes(start + 1, end)

