public class WeekdayCalculator {
    public static int getWeekdaysBetweenDates(LocalDateTime startDateTime, LocalDateTime endDateTime, ZoneId zoneId) {
        // Convert the given local date times to zoned date times using the provided zone id
        ZonedDateTime startZonedDateTime = startDateTime.atZone(zoneId);
        ZonedDateTime endZonedDateTime = endDateTime.atZone(zoneId);

        // Calculate the start date and end date based on the zoned date times
        LocalDate startDate = startZonedDateTime.toLocalDate();
        LocalDate endDate = endZonedDateTime.toLocalDate();

        // Initialize a counter for weekdays
        int weekdayCount = 0;

        // Iterate over the dates between the start and end date (inclusive) and check if each date is a weekday
        while (!startDate.isAfter(endDate)) {
            // Check if the current date is a weekday (Monday to Friday)
            if (startDate.getDayOfWeek().getValue() >= DayOfWeek.MONDAY.getValue() &&
                    startDate.getDayOfWeek().getValue() <= DayOfWeek.FRIDAY.getValue()) {
                // Increment the weekday count
                weekdayCount++;
            }

            // Move to the next date
            startDate = startDate.plusDays(1);
        }

        return weekdayCount;
    }

