Here is an implementation of the function to delete all occurrences of a given value in a singly linked list:

```python
class Node:
    def __init__(self, value):
        self.value = value
        self.next = None

def delete_occurrences(head, value):
    # Check if the linked list is empty
    if head is None:
        return head

    # Traverse through the linked list and keep track of the previous node
    current = head
    prev = None

    while current is not None:
        # If the value to be deleted is found, update the previous node's next pointer to skip the current node
        if current.value == value:
            if prev is None:
                # If the node to be deleted is the head, update the head pointer
                head = current.next
            else:
                prev.next = current.next
        else:
            # If the value is not found, continue to the next node
            prev = current

        current = current.next

    return head
```

