```python
import xml.sax

class XMLDictHandler(xml.sax.ContentHandler):
    def __init__(self):
        self.stack = []
        self.current_dict = {}
        self.text = ""

    def startElement(self, name, attrs):
        new_dict = {}
        new_dict["@attributes"] = attrs
        self.stack.append((self.current_dict, name, new_dict))
        self.current_dict[name] = new_dict
        self.current_dict = new_dict

    def endElement(self, name):
        if self.text:
            self.current_dict["#text"] = self.text
            self.text = ""
        if len(self.stack) > 0:
            parent, _, _ = self.stack.pop()
            self.current_dict = parent

    def characters(self, content):
        self.text += content.strip()

    def to_dict(self):
        return self.current_dict

def parse_xml(xml_str):
    handler = XMLDictHandler()
    xml.sax.parseString(xml_str, handler)
    return handler.to_dict()
```

