import java.util.HashMap;

public class StringConverter {

  public static HashMap<String, Integer> convertToCamelCaseAndCount(String str, String[] stopWords) {
    // Convert the string to camel case format and count word occurrences
    String[] words = str.split(" ");
    HashMap<String, Integer> wordCount = new HashMap<>();

    for (String word : words) {
      String formattedWord = formatWord(word);

      // Check if the word is a stop word
      if (!isStopWord(formattedWord, stopWords)) {
        wordCount.put(formattedWord, wordCount.getOrDefault(formattedWord, 0) + 1);
      }
    }

    return wordCount;
  }

  private static String formatWord(String word) {
    StringBuilder camelCaseWord = new StringBuilder();

    for (int i = 0; i < word.length(); i++) {
      char c = word.charAt(i);

      // Ignore non-alphabetic characters
      if (Character.isLetter(c)) {
        if (i == 0) {
          camelCaseWord.append(Character.toLowerCase(c));
        } else {
          camelCaseWord.append(Character.toUpperCase(c));
        }
      }
    }

    return camelCaseWord.toString();
  }

  private static boolean isStopWord(String word, String[] stopWords) {
    for (String stopWord : stopWords) {
      if (word.equals(stopWord)) {
        return true;
      }
    }

    return false;
  }

  public static void main(String[] args) {
    String str = "this is a great day";
    String[] stopWords = {"is", "a"};

    HashMap<String, Integer> wordCount = convertToCamelCaseAndCount(str, stopWords);

    // Print the word count
    for (String word : wordCount.keySet()) {
      System.out.println(word + ": " + wordCount.get(word));
    }
  }
}
