    def __init__(self, message):
        self.message = message

def fibonacci(n, memo={}):
    if n < 0:
        raise CustomException("Input value cannot be negative.")

    if n <= 1:
        return n

    if n not in memo:
        memo[n] = fibonacci(n-1, memo) + fibonacci(n-2, memo)

    return memo[n]
