function findSubstring(string, substring) {
  // Convert the string and substring to lowercase for case-insensitive comparison
  const lowerString = string.toLowerCase();
  const lowerSubstring = substring.toLowerCase();

  // Initialize variables to store the count and indices of substring occurrences
  let count = 0;
  const occurrences = [];

  // Iterate through each character in the string
  for (let i = 0; i < string.length; i++) {
    let match = true;

    // Check if the substring matches starting from the current character
    for (let j = 0; j < substring.length; j++) {
      // If the current characters don't match, break the inner loop
      if (lowerString[i + j] !== lowerSubstring[j]) {
        match = false;
        break;
      }
    }

    // If there is a match, increment the count and store the start and end indices
    if (match) {
      count++;
      occurrences.push({ start: i, end: i + substring.length - 1 });
    }
  }

  // Return the count and occurrences as an array
  return [count, occurrences];
}
```

