            if (isPrime(number)) {
                return number; // Return the largest prime found
            }
            number--;
        }
        return -1; // Return -1 if no prime number found
    }

    public static void main(String[] args) {
        int number = 50;
        int largestPrime = largestPrimeLessThan(number);
        System.out.println("Largest prime less than " + number + ": " + largestPrime);
    }
}
