import java.util.ArrayList;
import java.util.List;

public class NumberClassifier {

    public static void main(String[] args) {
        List<Integer> numbers = new ArrayList<>();
        numbers.add(-5);
        numbers.add(2);
        numbers.add(0);
        numbers.add(7);
        numbers.add(10);
        numbers.add(-12);
        numbers.add(11);

        List<Integer> evenNumbers = new ArrayList<>();
        List<Integer> oddNumbers = new ArrayList<>();
        List<Integer> positiveNumbers = new ArrayList<>();
        List<Integer> negativeNumbers = new ArrayList<>();
        List<Integer> primeNumbers = new ArrayList<>();

        classifyAndSeparateNumbers(numbers, evenNumbers, oddNumbers, positiveNumbers, negativeNumbers, primeNumbers);

        System.out.println("Even numbers: " + evenNumbers);
        System.out.println("Odd numbers: " + oddNumbers);
        System.out.println("Positive numbers: " + positiveNumbers);
        System.out.println("Negative numbers: " + negativeNumbers);
        System.out.println("Prime numbers: " + primeNumbers);
    }

    public static void classifyAndSeparateNumbers(List<Integer> numbers, List<Integer> evenNumbers, List<Integer> oddNumbers,
                                                  List<Integer> positiveNumbers, List<Integer> negativeNumbers, List<Integer> primeNumbers) {
        for (int number : numbers) {
            if (number % 2 == 0) {
                evenNumbers.add(number);
            } else {
                oddNumbers.add(number);
            }

            if (number > 0) {
                positiveNumbers.add(number);
            } else if (number < 0) {
                negativeNumbers.add(number);
            }

            if (isPrime(number)) {
                primeNumbers.add(number);
            }
        }
    }

    public static boolean isPrime(int number) {
        if (number <= 1) {
            return false;
        }

        for (int i = 2; i <= Math.sqrt(number); i++) {
            if (number % i == 0) {
                return false;
            }
        }

        return true;
    }
}
```

