```c
#include <stdio.h>

int isPrime(int n) {
    if (n <= 1) {
        return 0;
    }
    for (int i = 2; i * i <= n; i++) {
        if (n % i == 0) {
            return 0;
        }
    }
    return 1;
}

int main() {
    int num, sum = 0, count = 0, evenDivisibleBy3 = 0, primeOdd = 0, digitCount = 0;
    double average;

    printf("Enter a positive integer: ");
    scanf("%d", &num);

    while (num > 0) {
        int digit = num % 10;
        sum += digit;
        digitCount++;
        if (digit % 2 == 0 && digit % 3 == 0) {
            evenDivisibleBy3++;
        }
        if (digit % 2 != 0 && isPrime(digit)) {
            primeOdd++;
        }
        num /= 10;
    }

    average = (double) sum / digitCount;

    printf("Sum of digits: %d\n", sum);
    printf("Average of digits: %.2f\n", average);
    printf("Count of even digits divisible by 3: %d\n", evenDivisibleBy3);
    printf("Count of odd prime digits: %d\n", primeOdd);

