```c
#include <stdio.h>

void reverseString(char* str) {
    // If the string is empty or has only one character, return
    if (str == NULL || *str == '\0')
        return;

    // Find the end of the string
    char* end = str;
    while (*(end + 1) != '\0')
        end++;

    // Swap characters from both ends until the middle is reached
    while (str < end) {
        char temp = *str;
        *str = *end;
        *end = temp;

        str++;
        end--;
    }
}

