def longest_common_subsequence(a, b):
    # Create a matrix to store the lengths of common subsequences
    dp = [[0] * (len(b) + 1) for _ in range(len(a) + 1)]

    # Iterate through the strings to fill the matrix
    for i in range(1, len(a) + 1):
        for j in range(1, len(b) + 1):
            if a[i - 1] == b[j - 1]:
                # If the characters match, add 1 to the length of the previous subsequence
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                # If the characters don't match, take the maximum length of the previous subsequences
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    # Return the length of the longest common subsequence
    return dp[len(a)][len(b)]

