#include<iostream>

int sum(int a, int b) {
    // Iterate until there is no carry
    while (b != 0) {
        // Calculate the carry
        int carry = a & b;

        // Calculate the sum without carry
        a = a ^ b;

        // Set b as the carry, shifted by 1 position
        b = carry << 1;
    }

    return a;
}

