import java.util.Scanner;

public class PrimeNumbers {

    public static boolean isPrime(int num) {
        if (num <= 1) {
            return false;
        }
        for (int i = 2; i <= Math.sqrt(num); i++) {
            if (num % i == 0) {
                return false;
            }
        }
        return true;
    }

    public static int[] findClosestPrimeNumbers(int target, int[] numbers) {
        int[] closestPrimes = new int[10];
        int count = 0;
        int closestDiff = Integer.MAX_VALUE;

        for (int number : numbers) {
            if (isPrime(number)) {
                int diff = Math.abs(number - target);
                if (diff < closestDiff) {
                    count = 1;
                    closestPrimes[0] = number;
                    closestDiff = diff;
                } else if (diff == closestDiff) {
                    closestPrimes[count++] = number;
                }
            }
        }

        if (count < 10) {
            int[] remainingPrimes = new int[10 - count];
            int index = 0;
            for (int i = 2; i < Integer.MAX_VALUE && index < remainingPrimes.length; i++) {
                if (isPrime(i)) {
                    boolean isDuplicate = false;
                    for (int j = 0; j < count; j++) {
                        if (i == closestPrimes[j]) {
                            isDuplicate = true;
                            break;
                        }
                    }
                    if (!isDuplicate) {
                        remainingPrimes[index++] = i;
                    }
                }
            }
            for (int i = 0; i < remainingPrimes.length; i++) {
                closestPrimes[count++] = remainingPrimes[i];
            }
        }

        return closestPrimes;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.print("Enter the target number: ");
        int target = scanner.nextInt();

        System.out.print("Enter the number of elements in the array: ");
        int size = scanner.nextInt();

        int[] numbers = new int[size];
        System.out.print("Enter the elements of the array: ");
        for (int i = 0; i < size; i++) {
            numbers[i] = scanner.nextInt();
        }

        int[] closestPrimes = findClosestPrimeNumbers(target, numbers);

        System.out.println("The 10 closest prime numbers to " + target + " are:");
        for (int i = 0; i < closestPrimes.length; i++) {
            System.out.println(closestPrimes[i]);
        }

        scanner.close();
    }
}

