def convert_timestamp(timestamp):
    year = 1970
    month = 1
    day = 1
    hour = 0
    minute = 0
    second = 0

    while timestamp >= 31536000:  # number of seconds in a year
        if is_leap_year(year):
            if timestamp >= 31622400:
                timestamp -= 31622400
                year += 1
            else:
                break
        else:
            timestamp -= 31536000
            year += 1

    while timestamp >= 2592000:  # number of seconds in a month
        days_in_month = 31
        if month == 4 or month == 6 or month == 9 or month == 11:
            days_in_month = 30
        elif month == 2:
            if is_leap_year(year):
                days_in_month = 29
            else:
                days_in_month = 28
        if timestamp >= days_in_month * 86400:
            timestamp -= days_in_month * 86400
            month += 1
        else:
            break

    while timestamp >= 86400:  # number of seconds in a day
        timestamp -= 86400
        day += 1

    while timestamp >= 3600:  # number of seconds in an hour
        timestamp -= 3600
        hour += 1

    while timestamp >= 60:  # number of seconds in a minute
        timestamp -= 60
        minute += 1

    second = timestamp

    return f"{year:04d}-{month:02d}-{day:02d} {hour:02d}:{minute:02d}:{second:02d}"

