Here's a Swift code to find the maximum number from an array of integers using a recursive approach:

```swift
func findMaximum(arr: [Int]) -> (Int, Int)? {
    // Check for empty array
    guard !arr.isEmpty else {
        return nil
    }

    // Recursive helper function
    func findMaxHelper(arr: [Int], currentIndex: Int, currentMax: Int, maxIndex: Int) -> (Int, Int) {
        // Base case: reached the end of the array
        if currentIndex == arr.count {
            return (currentMax, maxIndex)
        }

        // Recursive case: compare the current element with the current maximum
        let element = arr[currentIndex]
        if element > currentMax {
            return findMaxHelper(arr: arr, currentIndex: currentIndex + 1, currentMax: element, maxIndex: currentIndex)
        } else {
            return findMaxHelper(arr: arr, currentIndex: currentIndex + 1, currentMax: currentMax, maxIndex: maxIndex)
        }
    }

    // Start the recursive function
    return findMaxHelper(arr: arr, currentIndex: 0, currentMax: Int.min, maxIndex: -1)
}

// Example usage
let arr = [2, 5, 3, 9, 1, 7, 6, 8]
if let (maxValue, maxIndex) = findMaximum(arr: arr) {
    print("Maximum value is \(maxValue) at index \(maxIndex)")
} else {
    print("Array is empty")
}
```

