#include<iostream>
using namespace std;

int findSecondLargest(int arr[], int size) {
  int largest = arr[0];    // initialize largest as first element
  int secondLargest = -1;  // initialize second largest as -1

  for(int i = 1; i < size; i++) {
    if(arr[i] > largest) {       // if current element is greater than largest
      secondLargest = largest;  // update second largest
      largest = arr[i];         // update largest
    } else if (arr[i] < largest && arr[i] > secondLargest) {  // if current element is smaller than largest and greater than second largest
      secondLargest = arr[i];   // update second largest
    }
  }

  return secondLargest;
}

