class SessionLogger implements Runnable {
    private List<User> users;
    private SimpleDateFormat dateFormat;

    public SessionLogger() {
        users = new ArrayList<>();
        dateFormat = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss");
    }

    public synchronized void addUser(User user) {
        users.add(user);
    }

    public synchronized void printSessionLog() {
        Collections.sort(users, Comparator.comparing(User::getEndTime));

        System.out.println("User\t\tStart Time\t\tEnd Time\t\tDuration (minutes)");
        for (User user : users) {
            long duration = (user.getEndTime().getTime() - user.getStartTime().getTime()) / (60 * 1000);
            System.out.println(user.getName() + "\t\t" + dateFormat.format(user.getStartTime()) + "\t\t" +
                    dateFormat.format(user.getEndTime()) + "\t\t" + duration);
        }
    }

