    public void run() {
        while (true) {
            try {
                Thread.sleep(1000); // Check every second
            } catch (InterruptedException e) {
                e.printStackTrace();
            }

            synchronized (this) {
                Iterator<User> iterator = users.iterator();
                while (iterator.hasNext()) {
                    User user = iterator.next();
                    long duration = (new Date().getTime() - user.getStartTime().getTime()) / (60 * 1000);
                    if (duration > 30) {
                        System.out.println(user.getName() + " exceeded the allowed session duration!");
                        iterator.remove();
                    }
                }
            }
        }
    }
}

