class Vector2D:
    def __init__(self, x: float, y: float):
        self.x = x
        self.y = y

    def get_x(self) -> float:
        return self.x

    def get_y(self) -> float:
        return self.y

    def magnitude(self) -> float:
        return (self.x ** 2 + self.y ** 2) ** 0.5

    def add(self, other: 'Vector2D') -> 'Vector2D':
        return Vector2D(self.x + other.x, self.y + other.y)

    def subtract(self, other: 'Vector2D') -> 'Vector2D':
        return Vector2D(self.x - other.x, self.y - other.y)

    def multiply(self, scalar: float) -> 'Vector2D':
        return Vector2D(self.x * scalar, self.y * scalar)

    def dot_product(self, other: 'Vector2D') -> float:
        return self.x * other.x + self.y * other.y

    def cross_product(self, other: 'Vector2D') -> float:
        return self.x * other.y - self.y * other.x

    def normalize(self) -> 'Vector2D':
        magnitude = self.magnitude()
        if magnitude == 0:
            return Vector2D(0, 0)
        return Vector2D(self.x / magnitude, self.y / magnitude)

    def distance(self, other: 'Vector2D') -> float:
        return ((self.x - other.x) ** 2 + (self.y - other.y) ** 2) ** 0.5

    def angle(self, other: 'Vector2D') -> float:
        dot_product = self.dot_product(other)
        magnitude_product = self.magnitude() * other.magnitude()
        if magnitude_product == 0:
            return 0
        return math.degrees(math.acos(dot_product / magnitude_product))

    def rotate(self, angle: float) -> 'Vector2D':
        angle_rad = math.radians(angle)
        cos_angle = math.cos(angle_rad)
        sin_angle = math.sin(angle_rad)
        new_x = self.x * cos_angle - self.y * sin_angle
        new_y = self.x * sin_angle + self.y * cos_angle
        return Vector2D(new_x, new_y)

    def project(self, other: 'Vector2D') -> 'Vector2D':
        dot_product = self.dot_product(other)
        magnitude_squared = other.magnitude() ** 2
        if magnitude_squared == 0:
            return Vector2D(0, 0)
        scalar = dot_product / magnitude_squared
        return other.multiply(scalar)

    def is_parallel(self, other: 'Vector2D') -> bool:
        return self.cross_product(other) == 0

