function sieveOfEratosthenes() {
  const maxRange = 10000;
  const primes = [];
  const isPrime = new Array(maxRange + 1).fill(true);
  isPrime[0] = false;
  isPrime[1] = false;

  for (let i = 2; i <= Math.sqrt(maxRange); i++) {
    if (isPrime[i]) {
      for (let j = i * i; j <= maxRange; j += i) {
        isPrime[j] = false;
      }
    }
  }

  for (let i = 0; i <= maxRange; i++) {
    if (isPrime[i]) {
      primes.push(i);
    }
  }

  const primeSum = primes.reduce((sum, prime) => sum + prime, 0);

