// Function to find the kth smallest distinct element in an unsorted array
int findKthSmallest(int arr[], int n, int k) {
    // Sort the array in ascending order
    sort(arr, arr + n);

    // Initialize variables
    int count = 1;
    int prev = arr[0];

    // Iterate through the sorted array
    for (int i = 1; i < n; i++) {
        // If current element is not equal to the previous element, increment the count
        if (arr[i] != prev) {
            count++;
        }

        // If the count is equal to k, return the current element
        if (count == k) {
            return arr[i];
        }

        // Update the previous element
        prev = arr[i];
    }

    // If kth smallest element does not exist, return -1
    return -1;
}

