Here is a Python program that converts a JSON string into an equivalent XML string:

```python
import json
import xml.etree.ElementTree as ET

def json_to_xml(json_string):
    def parse_element(element, parent):
        if isinstance(element, dict):
            for key, value in element.items():
                if isinstance(value, list):
                    for item in value:
                        child = ET.SubElement(parent, key)
                        parse_element(item, child)
                else:
                    child = ET.SubElement(parent, key)
                    parse_element(value, child)
        elif isinstance(element, list):
            for item in element:
                parse_element(item, parent)
        else:
            parent.text = str(element)

    data = json.loads(json_string)
    root = ET.Element('root')
    parse_element(data, root)
    xml_string = ET.tostring(root, encoding='utf-8', method='xml')
    return xml_string.decode('utf-8')

# Example usage
json_string = '{"employees":[{"firstName":"John", "lastName":"Doe"},{"firstName":"Anna", "lastName":"Smith"},{"firstName":"Peter", "lastName":"Jones"}]}'
xml_string = json_to_xml(json_string)
print(xml_string)
```

