import java.util.Scanner;

public class FibonacciSeries {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Prompt the user to enter the desired size of the series
        System.out.print("Enter the desired size of the Fibonacci series: ");
        int size = scanner.nextInt();

        // Validate the user input to ensure that the size entered is a positive integer
        while (size <= 0) {
            System.out.print("Invalid input! Enter a positive integer: ");
            size = scanner.nextInt();
        }

        // Prompt the user to choose whether to generate the series using recursion or iteration
        System.out.print("Choose the method to generate the series (1 - Recursion, 2 - Iteration): ");
        int method = scanner.nextInt();

        // Validate the user input to ensure that the method selected is either 1 or 2
        while (method != 1 && method != 2) {
            System.out.print("Invalid input! Choose either 1 or 2: ");
            method = scanner.nextInt();
        }

        // Generate and print the Fibonacci series
        if (method == 1) {
            System.out.println("Fibonacci series using recursion:");
            for (int i = 0; i < size; i++) {
                System.out.print(fibonacciRecursion(i) + " ");
            }
        } else if (method == 2) {
            System.out.println("Fibonacci series using iteration:");
            for (int i = 0; i < size; i++) {
                System.out.print(fibonacciIteration(i) + " ");
            }
        }

        // Calculate and display the sum, average, product, maximum, and minimum of the Fibonacci series
        long sum = 0;
        long product = 1;
        long maximum = 0;
        long minimum = Long.MAX_VALUE;
        int evenCount = 0;
        int oddCount = 0;
        int primeCount = 0;

        for (int i = 0; i < size; i++) {
            long fibonacciNumber = method == 1 ? fibonacciRecursion(i) : fibonacciIteration(i);
            sum += fibonacciNumber;
            product *= fibonacciNumber;
            maximum = Math.max(maximum, fibonacciNumber);
            minimum = Math.min(minimum, fibonacciNumber);

            if (fibonacciNumber % 2 == 0) {
                evenCount++;
            } else {
                oddCount++;
            }

            if (isPrime(fibonacciNumber)) {
                primeCount++;
            }
        }

        double average = (double) sum / size;

        System.out.println("\nSum: " + sum);
        System.out.println("Average: " + average);
        System.out.println("Product: " + product);
        System.out.println("Maximum: " + maximum);
        System.out.println("Minimum: " + minimum);
        System.out.println("Even Count: " + evenCount);
        System.out.println("Odd Count: " + oddCount);
        System.out.println("Prime Count: " + primeCount);

        scanner.close();
    }

    // Generate the Fibonacci series using recursion
    public static long fibonacciRecursion(int n) {
        if (n <= 1) {
            return n;
        }

        return fibonacciRecursion(n - 1) + fibonacciRecursion(n - 2);
    }

    // Generate the Fibonacci series using iteration
    public static long fibonacciIteration(int n) {
        if (n <= 1) {
            return n;
        }

        long firstNumber = 0;
        long secondNumber = 1;
        long fibonacciNumber = 0;

        for (int i = 2; i <= n; i++) {
            fibonacciNumber = firstNumber + secondNumber;
            firstNumber = secondNumber;
            secondNumber = fibonacciNumber;
        }

        return fibonacciNumber;
    }

    // Check if a number is prime
    public static boolean isPrime(long number) {
        if (number <= 1) {
            return false;
        }

        for (int i = 2; i <= Math.sqrt(number); i++) {
            if (number % i == 0) {
                return false;
            }
        }

        return true;
    }
}

