import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.LinkedBlockingQueue;

public class DynamicThreadPool {

    private final int MAX_THREADS;
    private final int MIN_THREADS;
    private final int INITIAL_THREADS;
    private final long THREAD_TIMEOUT;
    private final Queue<Runnable> tasks;
    private final BlockingQueue<ThreadPoolWorker> workers;
    private final ExecutorService executor;

    public DynamicThreadPool(int maxThreads, int minThreads, int initialThreads, long threadTimeout) {
        this.MAX_THREADS = maxThreads;
        this.MIN_THREADS = minThreads;
        this.INITIAL_THREADS = initialThreads;
        this.THREAD_TIMEOUT = threadTimeout;
        this.tasks = new PriorityQueue<>(Comparator.comparingInt(Task::getPriority));
        this.workers = new LinkedBlockingQueue<>();
        this.executor = Executors.newFixedThreadPool(maxThreads);
        initializeThreadPool();
    }

    private void initializeThreadPool() {
        for (int i = 0; i < INITIAL_THREADS; i++) {
            ThreadPoolWorker worker = new ThreadPoolWorker();
            workers.add(worker);
            executor.execute(worker);
        }
    }

    public void submit(Runnable task, int priority) {
        tasks.add(new Task(task, priority));
        synchronized (workers) {
            if (workers.size() < tasks.size() && workers.size() < MAX_THREADS) {
                ThreadPoolWorker worker = new ThreadPoolWorker();
                workers.add(worker);
                executor.execute(worker);
            }
        }
    }

    public Future<?> submit(Callable<?> task, int priority) {
        tasks.add(new Task(task, priority));
        synchronized (workers) {
            if (workers.size() < tasks.size() && workers.size() < MAX_THREADS) {
                ThreadPoolWorker worker = new ThreadPoolWorker();
                workers.add(worker);
                executor.execute(worker);
            }
        }
        return executor.submit(task);
    }

    private class ThreadPoolWorker implements Runnable {
        private volatile boolean running = true;

        @Override
        public void run() {
            while (running) {
                try {
                    Runnable task = tasks.poll();
                    if (task != null) {
                        task.run();
                    } else {
                        synchronized (workers) {
                            if (workers.size() > MIN_THREADS) {
                                workers.remove(this);
                                running = false;
                            } else {
                                workers.wait(THREAD_TIMEOUT);
                            }
                        }
                    }
                } catch (InterruptedException e) {
                    // Handle interruption gracefully
                    Thread.currentThread().interrupt();
                } catch (Exception e) {
                    // Handle exception and log appropriately
                    e.printStackTrace();
                }
            }
        }

        public void stop() {
            running = false;
            Thread.currentThread().interrupt();
        }
    }

    private class Task implements Runnable, Comparable<Task> {
        private final Runnable task;
        private final int priority;

        public Task(Runnable task, int priority) {
            this.task = task;
            this.priority = priority;
        }

        public Task(Callable<?> task, int priority) {
            this.task = Executors.callable(task);
            this.priority = priority;
        }

        @Override
        public void run() {
            task.run();
        }

        public int getPriority() {
            return priority;
        }

        @Override
        public int compareTo(Task other) {
            return Integer.compare(other.priority, priority);
        }
    }
}
```

This implementation uses a priority queue to prioritize tasks based on their urgency, and the thread pool dynamically resizes based on the current workload. The `submit()` method is used to submit both `Runnable` and `Callable` tasks with an associated priority. The `ThreadPoolWorker` class represents the worker thread that executes the tasks. The `Task` class wraps the submitted task and its priority.

The thread pool also handles exceptions gracefully by catching them within the worker thread's `run()` method and providing appropriate logging. The worker thread can be interrupted to stop its execution.

