function isPalindrome(list) {
  // Convert each string in the list to lowercase and remove non-alphabetic characters
  let cleanList = list.map(str => str.toLowerCase().replace(/[^a-z]/g, ''));

  // Concatenate the strings in reverse order
  let reversed = cleanList.reduceRight((acc, str) => acc + str, '');

  // Check if the reversed string is the same as the original list
  return reversed === cleanList.join('');
}
