Here is a C++ program that calculates the mean, median, and mode of an array of integer numbers:

```cpp
#include <iostream>
#include <vector>
#include <algorithm>
#include <map>

// Function to calculate the mean
int calculateMean(const std::vector<int>& arr) {
    if (arr.empty()) {
        std::cout << "Error: Array is empty." << std::endl;
        return 0;
    }

    long long sum = 0;
    for (int num : arr) {
        sum += num;
    }

    return sum / arr.size();
}

// Function to calculate the median
int calculateMedian(const std::vector<int>& arr) {
    if (arr.empty()) {
        std::cout << "Error: Array is empty." << std::endl;
        return 0;
    }

    std::vector<int> sortedArr(arr);
    std::sort(sortedArr.begin(), sortedArr.end());

    int size = arr.size();
    if (size % 2 == 0) {
        return (sortedArr[size / 2 - 1] + sortedArr[size / 2]) / 2;
    } else {
        return sortedArr[size / 2];
    }
}

// Function to calculate the mode
std::vector<int> calculateMode(const std::vector<int>& arr) {
    if (arr.empty()) {
        std::cout << "Error: Array is empty." << std::endl;
        return {};
    }

    std::map<int, int> freqMap;
    int maxFreq = 0;
    for (int num : arr) {
        freqMap[num]++;
        maxFreq = std::max(maxFreq, freqMap[num]);
    }

    std::vector<int> modes;
    for (const auto& pair : freqMap) {
        if (pair.second == maxFreq) {
            modes.push_back(pair.first);
        }
    }

    return modes;
}

int main() {
    // Example usage
    std::vector<int> arr = {2, 4, 5, 2, 6, 4, 5, 2, 3, 6, 7, 2, 2, 3, 6};

    int mean = calculateMean(arr);
    std::cout << "Mean: " << mean << std::endl;

    int median = calculateMedian(arr);
    std::cout << "Median: " << median << std::endl;

    std::vector<int> modes = calculateMode(arr);
    std::cout << "Mode: ";
    for (int mode : modes) {
        std::cout << mode << " ";
    }
    std::cout << std::endl;

    return 0;
}
```

This program defines three functions: `calculateMean`, `calculateMedian`, and `calculateMode`, which calculate the mean, median, and mode of the given array respectively.

