def largest_prime_palindrome_divisible_by_3(lst):
    def helper(lst, current_max):
        if not lst:
            return current_max

        num = lst.pop()
        if num % 3 == 0 and is_palindrome(num) and is_prime(num):
            current_max = max(current_max, num)

        return helper(lst, current_max)

    return helper(lst, -1)

